import itertools

# Set the parameters
r = 2/3
S = [0, 1, 2, 3, 4]

# Step 1: Calculate P1 (differences)
P1 = set()
for s1 in S:
    for s2 in S:
        P1.add(s1 - s2)
P1_list = list(P1)

# Step 2: Calculate P2 = {3*r*p*q | p, q in P1}
P2 = set()
for p in P1:
    for q in P1:
        P2.add(3 * r * p * q)

# Step 3: Calculate P3 = {x^2 + y^2 - z^2 - w^2 | x, y, z, w in P1}
P3 = set()
for x in P1:
    for y in P1:
        for z in P1:
            for w in P1:
                P3.add(x**2 + y**2 - z**2 - w**2)

# Step 4: Check if P2 is a subset of P3
is_subset = P2.issubset(P3)

print(f"P1 size: {len(P1)}")
print(f"P2 size: {len(P2)}")
print(f"P3 size: {len(P3)}")
print(f"Is P2 a subset of P3? {is_subset}")

# Verification of a tricky element if the test fails (optional, but good for debugging)
if not is_subset:
    print("Elements in P2 but not in P3:")
    for val in P2:
        if val not in P3:
            print(val)

